  "introZh": "★【長江行·攬月號/極光號核心亮點】\r\n★2026年首航3億打造長江新船王三峽遊輪·首搭鴻蒙智能艙房系統\r\n★真·一價全包：含船上三餐+免費WIFI+指定酒水暢飲+自助洗衣+三峽大壩升船機體驗+葛洲壩過閘體驗。\r\n★全覽長江三峽·奇景盡收：瞿塘峽、巫峽、西陵峽，日間全景漫遊。\r\n★一次航程，兩大工程奇跡與三峽自然壯景交匯。\r\n★【江南全覽】上海，杭州，蘇州，無錫，南京，烏鎮。\r\n★【超棒全景，精華全含】烏鎮景區，西湖景區，夫子廟，大報恩寺遺址公園，錫惠公園，寄暢園，惠山古鎮，太湖風景區，盤門，金雞湖風景區，上海灘：各有各的歷史，各有各的風情。\r\n★【A+級明星產品】暢銷版萬人好評，滿意度、性價比超級高。\r\n★【特色美食】 杭州: 西湖醋魚，南宋風味宴；無錫: 無錫排骨，太湖乾隆宴; 南京: 鹽水鴨，淮陽風味宴; 蘇州: 特色鱸魚，水鄉風味宴",
