    "descZh": "抵达上海 Arrive in Shanghai\n抵达上海机场（PVG or SHA）或虹桥高铁站，接机/接站后送回酒店休息。相邻2小时内的航班/车次的客人，我们将统一安排车辆接送，接机/接站可能会有等待现象，敬请谅解！（酒店14:00后可办理入住，具体接机/接站资讯和酒店详情请见出团通知书）\n浦东机场接机汇合点：1号航站楼抵达层10号门内侧；2号航站楼抵达层“星巴克咖啡店”门口。\n虹桥机场接机汇合点：2号航站楼抵达层KFC肯德基门口。\n虹桥高铁站抵达的客人请通过走廊前往虹桥机场2号航站楼接机汇合点集合。\n虹桥机场1号航站楼抵达的客人请乘坐航站楼摆渡车前往2号航站楼接机汇合点集合。\n住宿：上海三甲港绿地铂派酒店或同级酒店",
