    "descZh": "上海/乌镇/杭州Shanghai/Wuzhen/Hangzhou(B/L)\n早餐后驱车前往游览被称为“中国最后的枕水人家”【乌镇】。乌镇是中国历史文化名镇、国家5A级景区，也因刘若英主演的《似水年华》在此取景而闻名海内外。参观健康家居体验馆。随后前往具有人间天堂美誉的杭州，抵达后游览杭州新晋网红景点【城市阳台】，在此可观钱塘江，眺望杭州亚运会场馆。随后前往游览【西湖景区】，环湖山峦迭翠，花木繁茂。远眺柳浪闻莺，三潭印月，雷峰夕照等西湖十景，名自景始，景以名传。漫步西湖，无限情调尽在此刻。\n住宿：杭州浦京花园大酒店或同级酒店",
