    "descZh": "杭州/南京Hangzhou/Nanjing(B/L)\n早餐后前往龙井茶村体验独特茶乡风情，品尝中国国茶龙井。随后前往南京，南京是中国四大古都之一、首批国家历史文化名城 。游览【东水关遗址公园】，公园将水关建筑与城墙建筑融为一体，具有“古桥、古河、古墙、古闸”四古之称。继而前往“烟笼寒水月笼沙，夜泊秦淮近酒家”的秦淮河畔【夫子庙】，是南京十里秦淮风光带上的最重要景点。茶肆酒楼商铺林立，是中国著名的开放式国家5A级旅游景区和国际旅游胜地。\n住宿：南京汪海国际大酒店或同级酒店",
