    "descZh": "南京/无锡Nanjing/Wuxi(B/L)\n早餐后前往游览历史悠久的【大报恩寺】，与灵谷寺、天界寺并称为金陵三大寺。欣赏水晶内画展览。随后参观玉器博览中心，南京素有石头城之称，他的玉雕和浙江的东扬木雕齐名。午餐后前往无锡，游览江南著名“两园一镇”：【锡惠公园】，【寄畅园】和【惠山古镇】。锡惠公园是太湖风景区的核心景点，寄畅园是康熙和乾隆二帝来江南的必游之地，就连北京颐和园内的谐趣园，以及圆明园内的廓然大公（已毁于战火），也是仿寄畅园而建。随后参观紫砂壶博物馆。\n住宿：无锡华怡名都大酒店或同级酒店",
    "descEn": "南京/无锡Nanjing/Wuxi(B/L)\n早餐后前往游览历史悠久的【大报恩寺】，与灵谷寺、天界寺并称为金陵三大寺。欣赏水晶内画展览。随后参观玉器博览中心，南京素有石头城之称，他的玉雕和浙江的东扬木雕齐名。午餐后前往无锡，游览江南著名“两园一镇”：【锡惠公园】，【寄畅园】和【惠山古镇】。锡惠公园是太湖风景区的核心景点，寄畅园是康熙和乾隆二帝来江南的必游之地，就连北京颐和园内的谐趣园，以及圆明园内的廓然大公（已毁于战火），也是仿寄畅园而建。随后参观紫砂壶博物馆。\n住宿：无锡华怡名都大酒店或同级酒店",
