    "descZh": "无锡/苏州Wuxi/Suzhou(B/L)\n早餐后前往如诗如画的【蠡湖公园】赏太湖风光，园中“春之媚、夏之秀、秋之韵、冬之凝”四大景观巧布，以四季花木展现江南秀色。以水绕园，随水赋景，季节转换时空,林木变奏韵律,人与自然谐合之代表作。参观太湖珍珠馆。午餐后驱车前往苏州，外观【盘门】，盘门是春秋战国时期伍子胥所筑苏州城的八座城门之一，是中国现存最完整的水陆并联城门。古城门，古拱桥，古运河，一同见证了苏州2500年的历史变迁。\n住宿：苏州维也纳国际酒店或同级酒店",
