    "descZh": "苏州/上海 Suzhou/Shanghai(B/L)\n早餐后参观蚕丝工厂。游览【金鸡湖风景区】，中国最大的城市湖泊公园，堪称二十一世纪苏州“人间新天堂”的象征。远观【东方之门】和【苏州鸟巢】，都是延续了苏州悠久历史、展示苏州现代文明的崭新建筑。午餐后返回上海，参观宝石会所和中医养生中心，游览黄浦江畔的【外滩】，见证历史的“万国建筑博览群”和浦东陆家嘴的东方明珠和上海中心等摩登建筑隔江相望。漫步江边，品味“十里洋场烟花地，风云际会上海滩”。\n住宿：上海三甲港绿地铂派酒店或同级酒店",
